export const shopCat = (slug) => SHOP.find((c) => c.slug === slug)
export const inCat = (slug) => PRODUCTS.filter((p) => p.category === slug)
export const subSlug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')

// "FANCY 1404 drawer knob, Antique, Small": what the enquiry carries
export function itemLabel(p, finish, size) {
  const base = p.name.toUpperCase().startsWith(p.brand) ? p.name : `${p.brand} ${p.name}`
  return [base, finish, size].filter(Boolean).join(', ')
}

export const photoNote = (p) => `Photo from the ${p.brand} catalogue`

// Compact rows for the catalogue search (served as /catalogue/search.json, loaded on demand)
export const searchRows = () => PRODUCTS.map((p) => ({
  id: p.id, n: p.name, c: p.code || '', b: p.brand, k: p.category, s: p.subcategory, f: p.finishes.join(' · '),
  u: p.url, i: p.images[0]?.thumb || p.images[0]?.src || null, w: p.images[0]?.w, h: p.images[0]?.h,
  m: [p.finishes.length ? `${p.finishes.length} finish${p.finishes.length > 1 ? 'es' : ''}` : '', p.sizes.length ? `${p.sizes.length} size${p.sizes.length > 1 ? 's' : ''}` : '', p.code ? `Model ${p.code}` : ''].filter(Boolean).join(' · '),
  white: p.brand === 'ROOT' && !p.images[0]?.view?.startsWith('in a wardrobe'),
}))
